// Normalize the many shapes n8n's Email Trigger emits across versions.
// Modern versions of Node Mail parse `to` / `from` as arrays of
// { address, name } objects, older ones as raw strings.
const m = $input.item.json;

function parseAddr(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) {
    if (v.length === 0) return '';
    if (typeof v[0] === 'string') return v[0];
    return v[0].address || '';
  }
  if (v.value && Array.isArray(v.value) && v.value[0]) return v.value[0].address || '';
  return v.address || '';
}

return {
  json: {
    to: parseAddr(m.to),
    from: parseAddr(m.from),
    subject: m.subject || '',
    text: m.text || m.textAsHtml || '',
    html: m.html || '',
    messageId: m.messageId || '',
    inReplyTo: m.inReplyTo || ''
  }
};
